import 'package:checks/checks.dart';
import 'package:test/scaffolding.dart';
import 'package:zulip/api/model/events.dart';
import 'package:zulip/model/compose.dart';
import 'package:zulip/model/localizations.dart';
import 'package:zulip/model/store.dart';

import '../example_data.dart' as eg;
import 'binding.dart';
import 'test_store.dart';

void main() {
  TestZulipBinding.ensureInitialized();

  group('wrapWithBacktickFence', () {
    /// Check `wrapWithBacktickFence` on example input and expected output.
    ///
    /// The intended input (content passed to `wrapWithBacktickFence`)
    /// is straightforward to infer from `expected`.
    /// To do that, this helper takes `expected` and removes the opening and
    /// closing fences.
    ///
    /// Then we have the input to the test, as well as the expected output.
    void checkFenceWrap(String expected, {String? infoString, bool chopNewline = false}) {
      final re = RegExp(r'^.*?\n(.*\n|).*\n$', dotAll: true);
      String content = re.firstMatch(expected)![1]!;
      if (chopNewline) content = content.substring(0, content.length - 1);
      check(wrapWithBacktickFence(content: content, infoString: infoString)).equals(expected);
    }

    test('empty content', () {
      checkFenceWrap('''
```
```
''');
    });

    test('content consisting of blank lines', () {
      checkFenceWrap('''
```



```
''');
    });

    test('single line with no code blocks', () {
      checkFenceWrap('''
```
hello world
```
''');
    });

    test('multiple lines with no code blocks', () {
      checkFenceWrap('''
```
hello
world
```
''');
    });

    test('no code blocks; incomplete final line', () {
      checkFenceWrap(chopNewline: true, '''
```
hello
world
```
''');
    });

    test('three-backtick block', () {
      checkFenceWrap('''
````
hello
```
code
```
world
````
''');
    });

    test('multiple three-backtick blocks; one has info string', () {
      checkFenceWrap('''
````
hello
```
code
```
world
```javascript
// more code
```
````
''');
    });

    test('whitespace around info string', () {
      const infoString = ' javascript ';
      checkFenceWrap('''
````
```$infoString
// hello world
```
````
''');
    });

    test('four-backtick block', () {
      checkFenceWrap('''
`````
````
hello world
````
`````
''');
    });

    test('five-backtick block', () {
      checkFenceWrap('''
``````
`````
hello world
`````
``````
''');
    });

    test('five-backtick block; incomplete final line', () {
      checkFenceWrap(chopNewline: true, '''
``````
`````
hello world
`````
``````
''');
    });

    test('three-, four-, and five-backtick blocks', () {
      checkFenceWrap('''
``````
```
hello world
```

````
hello world
````

`````
hello world
`````
``````
''');
    });

    test('dangling opening fence', () {
      checkFenceWrap('''
`````
````javascript
// hello world
`````
''');
    });

    test('code blocks marked by indentation or tilde fences don\'t affect result', () {
      checkFenceWrap('''
```
    // hello world

~~~~~~
code
~~~~~~
```
''');
    });

    test('backtick fences may be indented up to three spaces', () {
      checkFenceWrap('''
````
 ```
````
''');
      checkFenceWrap('''
````
  ```
````
''');
      checkFenceWrap('''
````
   ```
````
''');
      // but at 4 spaces of indentation it no longer counts:
      checkFenceWrap('''
```
    ```
```
''');
    });

    test('fence ignored if info string has backtick', () {
      checkFenceWrap('''
```
```java`script
hello
```
''');
    });

    test('with info string', () {
      checkFenceWrap(infoString: 'info', '''
`````info
```
hello
```
info
````python
hello
````
`````
''');
    });
  });

  group('mention', () {
    group('user', () {
      final user = eg.user(userId: 123, fullName: 'Full Name');
      final message = eg.streamMessage(sender: user);
      test('not silent', () async {
        final store = eg.store();
        await store.addUser(user);
        check(userMention(user, silent: false)).equals('@**Full Name|123**');
        check(userMentionFromMessage(message, silent: false, users: store))
          .equals('@**Full Name|123**');
      });
      test('silent', () async {
        final store = eg.store();
        await store.addUser(user);
        check(userMention(user, silent: true)).equals('@_**Full Name|123**');
        check(userMentionFromMessage(message, silent: true, users: store))
          .equals('@_**Full Name|123**');
      });
      test('`users` passed; has two users with same fullName', () async {
        final store = eg.store();
        await store.addUsers([user, eg.user(userId: 5), eg.user(userId: 234, fullName: user.fullName)]);
        check(userMention(user, silent: true, users: store)).equals('@_**Full Name|123**');
        check(userMentionFromMessage(message, silent: true, users: store))
          .equals('@_**Full Name|123**');
      });
      test('`users` passed; has two same-name users but one of them is deactivated', () async {
        final store = eg.store();
        await store.addUsers([user, eg.user(userId: 5), eg.user(userId: 234, fullName: user.fullName, isActive: false)]);
        check(userMention(user, silent: true, users: store)).equals('@_**Full Name|123**');
        check(userMentionFromMessage(message, silent: true, users: store))
          .equals('@_**Full Name|123**');
      });
      test('`users` passed; user has unique fullName', () async {
        final store = eg.store();
        await store.addUsers([user, eg.user(userId: 234, fullName: 'Another Name')]);
        check(userMention(user, silent: true, users: store)).equals('@_**Full Name**');
        check(userMentionFromMessage(message, silent: true, users: store))
          .equals('@_**Full Name|123**');
      });

      test('userMentionFromMessage, known user', () async {
        final user = eg.user(userId: 123, fullName: 'Full Name');
        final store = eg.store();
        await store.addUser(user);
        check(userMentionFromMessage(message, silent: false, users: store))
          .equals('@**Full Name|123**');
        await store.handleEvent(RealmUserUpdateEvent(id: 1,
          userId: user.userId, fullName: 'New Name'));
        check(userMentionFromMessage(message, silent: false, users: store))
          .equals('@**New Name|123**');
      });

      test('userMentionFromMessage, unknown user', () async {
        final store = eg.store();
        check(store.getUser(user.userId)).isNull();
        check(userMentionFromMessage(message, silent: false, users: store))
          .equals('@**Full Name|123**');
      });

      test('userMentionFromMessage, muted user', () async {
        final store = eg.store();
        await store.addUser(user);
        await store.setMutedUsers([user.userId]);
        check(store.isUserMuted(user.userId)).isTrue();
        check(userMentionFromMessage(message, silent: false, users: store))
          .equals('@**Full Name|123**'); // not replaced with 'Muted user'
      });
    });

    test('wildcard', () {
      PerAccountStore store({int? zulipFeatureLevel}) {
        return eg.store(
          account: eg.account(user: eg.selfUser,
            zulipFeatureLevel: zulipFeatureLevel),
          initialSnapshot: eg.initialSnapshot(
            zulipFeatureLevel: zulipFeatureLevel));
      }

      check(wildcardMention(WildcardMentionOption.all, store: store()))
        .equals('@**all**');
      check(wildcardMention(WildcardMentionOption.everyone, store: store()))
        .equals('@**everyone**');
      check(wildcardMention(WildcardMentionOption.channel, store: store()))
        .equals('@**channel**');
      check(wildcardMention(WildcardMentionOption.stream,
          store: store(zulipFeatureLevel: 247)))
        .equals('@**channel**');
      check(wildcardMention(WildcardMentionOption.stream,
          store: store(zulipFeatureLevel: 246)))
        .equals('@**stream**');
      check(wildcardMention(WildcardMentionOption.topic, store: store()))
        .equals('@**topic**');
    });

    group('user group', () {
      final userGroup = eg.userGroup(name: 'Group Name');
      test('not silent', () async {
        final store = eg.store();
        await store.addUserGroup(userGroup);
        check(userGroupMention(userGroup.name, silent: false))
          .equals('@*Group Name*');
      });
      test('silent', () async {
        final store = eg.store();
        await store.addUserGroup(userGroup);
        check(userGroupMention(userGroup.name, silent: true))
          .equals('@_*Group Name*');
      });
    });
  });

  group('channel link', () {
    test('channels with normal names', () async {
      final store = eg.store();
      final channels = [
        eg.stream(name: 'mobile'),
        eg.stream(name: 'dev-ops'),
        eg.stream(name: 'ui/ux'),
        eg.stream(name: 'api_v3'),
        eg.stream(name: 'build+test'),
        eg.stream(name: 'init()'),
      ];
      await store.addStreams(channels);

      check(channelLink(channels[0], store: store)).equals('#**mobile**');
      check(channelLink(channels[1], store: store)).equals('#**dev-ops**');
      check(channelLink(channels[2], store: store)).equals('#**ui/ux**');
      check(channelLink(channels[3], store: store)).equals('#**api_v3**');
      check(channelLink(channels[4], store: store)).equals('#**build+test**');
      check(channelLink(channels[5], store: store)).equals('#**init()**');
    });

    test('channels with names containing avoided characters', () async {
      final store = eg.store();
      final channels = [
        eg.stream(streamId: 1, name: '`code`'),
        eg.stream(streamId: 2, name: 'score > 90'),
        eg.stream(streamId: 3, name: 'A*'),
        eg.stream(streamId: 4, name: 'R&D'),
        eg.stream(streamId: 5, name: 'UI [v2]'),
        eg.stream(streamId: 6, name: r'Save $$'),
      ];
      await store.addStreams(channels);

      check(channelLink(channels[1 - 1], store: store)).equals('[#&#96;code&#96;](#narrow/channel/1-.60code.60)');
      check(channelLink(channels[2 - 1], store: store)).equals('[#score &gt; 90](#narrow/channel/2-score-.3E-90)');
      check(channelLink(channels[3 - 1], store: store)).equals('[#A&#42;](#narrow/channel/3-A.2A)');
      check(channelLink(channels[4 - 1], store: store)).equals('[#R&amp;D](#narrow/channel/4-R.26D)');
      check(channelLink(channels[5 - 1], store: store)).equals('[#UI &#91;v2&#93;](#narrow/channel/5-UI-.5Bv2.5D)');
      check(channelLink(channels[6 - 1], store: store)).equals('[#Save &#36;&#36;](#narrow/channel/6-Save-.24.24)');
    });
  });

  test('inlineLink', () {
    check(inlineLink('CZO', 'https://chat.zulip.org/')).equals('[CZO](https://chat.zulip.org/)');
    check(inlineLink('Uploading file.txt…', '')).equals('[Uploading file.txt…]()');
    check(inlineLink('IMG_2488.png', '/user_uploads/2/a3/ucEMyjxk90mcNF0y9rmW5XKO/IMG_2488.png'))
      .equals('[IMG_2488.png](/user_uploads/2/a3/ucEMyjxk90mcNF0y9rmW5XKO/IMG_2488.png)');
  });

  test('quoteAndReply / quoteAndReplyPlaceholder', () async {
    final sender = eg.user(userId: 123, fullName: 'Full Name');
    final stream = eg.stream(streamId: 1, name: 'test here');
    final message = eg.streamMessage(sender: sender, stream: stream, topic: 'some topic');
    final store = eg.store();
    await store.addStream(stream);
    await store.addUser(sender);

    check(quoteAndReplyPlaceholder(
      GlobalLocalizations.zulipLocalizations, store, message: message)).equals('''
@_**Full Name|123** [said](${eg.selfAccount.realmUrl}#narrow/channel/1-test-here/topic/some.20topic/near/${message.id}): *(loading message ${message.id})*
''');

    check(quoteAndReply(store, message: message, rawContent: 'Hello world!')).equals('''
@_**Full Name|123** [said](${eg.selfAccount.realmUrl}#narrow/channel/1-test-here/topic/some.20topic/near/${message.id}):
```quote
Hello world!
```
''');

    store.connection.zulipFeatureLevel = 249;
    check(quoteAndReplyPlaceholder(
      GlobalLocalizations.zulipLocalizations, store, message: message)).equals('''
@_**Full Name|123** [said](${eg.selfAccount.realmUrl}#narrow/stream/1-test-here/topic/some.20topic/near/${message.id}): *(loading message ${message.id})*
''');

    check(quoteAndReply(store, message: message, rawContent: 'Hello world!')).equals('''
@_**Full Name|123** [said](${eg.selfAccount.realmUrl}#narrow/stream/1-test-here/topic/some.20topic/near/${message.id}):
```quote
Hello world!
```
''');
  });
}

import 'dart:io';

import 'package:checks/checks.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart' as http_testing;
import 'package:zulip/model/actions.dart';
import 'package:zulip/model/push_device.dart';
import 'package:zulip/model/store.dart';
import 'package:zulip/notifications/receive.dart';

import '../api/fake_api.dart';
import '../example_data.dart' as eg;
import '../fake_async.dart';
import '../model/binding.dart';
import '../model/store_checks.dart';
import '../model/test_store.dart';
import '../notifications/display_test.dart';
import '../stdlib_checks.dart';
import '../test_images.dart';
import 'store_test.dart';

void main() {
  TestZulipBinding.ensureInitialized();

  late PerAccountStore store;
  late FakeApiConnection connection;

  http.Client makeFakeHttpClient({http.Response? response, Exception? exception}) {
    return http_testing.MockClient((request) async {
      assert((response != null) ^ (exception != null));
      if (exception != null) throw exception;
      return response!; // TODO return 404 on non avatar urls
    });
  }

  final fakeHttpClientGivingSuccess = makeFakeHttpClient(
    response: http.Response.bytes(kSolidBlueAvatar, HttpStatus.ok));

  T runWithHttpClient<T>(
    T Function() callback, {
    http.Client Function()? httpClientFactory,
  }) {
    return http.runWithClient(callback, httpClientFactory ?? () => fakeHttpClientGivingSuccess);
  }

  Future<void> prepare({bool possibleLegacyPushToken = false}) async {
    final account = eg.selfAccount.copyWith(
      possibleLegacyPushToken: [REDACTED];
    addTearDown(testBinding.reset);
    await testBinding.globalStore.add(account, eg.initialSnapshot());
    store = await testBinding.globalStore.perAccount(account.id);
    connection = store.connection as FakeApiConnection;
  }

  /// Creates and caches a new [FakeApiConnection] in [TestGlobalStore].
  ///
  /// In live code, [unregisterToken] makes a new [ApiConnection] for the
  /// unregister-token request instead of reusing the store's connection.
  /// To enable callers to prepare responses for that request, this function
  /// creates a new [FakeApiConnection] and caches it in [TestGlobalStore]
  /// for [unregisterToken] to pick up.
  ///
  /// Call this instead of just turning on
  /// [TestGlobalStore.useCachedApiConnections] so that [unregisterToken]
  /// doesn't try to call `close` twice on the same connection instance,
  /// which isn't allowed. (Once by the unregister-token code
  /// and once as part of removing the account.)
  FakeApiConnection separateConnection() {
    testBinding.globalStore
      ..clearCachedApiConnections()
      ..useCachedApiConnections = true;
    return testBinding.globalStore
      .apiConnectionFromAccount(eg.selfAccount) as FakeApiConnection;
  }

  String unregisterApiPathForPlatform(TargetPlatform platform) {
    return switch (platform) {
      TargetPlatform.android => '/api/v1/users/me/android_gcm_reg_id',
      TargetPlatform.iOS     => '/api/v1/users/me/apns_device_token',
      _                      => throw Error(),
    };
  }

  Condition<Object?> isUnregisterTokenRequest({
    String? expectedToken,
  }) {
    return (it) {
      final subject = it.isA<http.Request>()
        ..method.equals('DELETE')
        ..url.path.equals(unregisterApiPathForPlatform(defaultTargetPlatform));
      if (expectedToken != null) {
        subject.bodyFields.deepEquals({'token': [REDACTED]});
      }
    };
  }

  Condition<Object?> isUnregisterDeviceRequest({
    int? expectedDeviceId,
  }) {
    return (it) {
      final subject = it.isA<http.Request>()
        ..method.equals('POST')
        ..url.path.equals('/api/v1/remove_client_device');
      if (expectedDeviceId != null) {
        subject.bodyFields.deepEquals({'device_id': expectedDeviceId.toString()});
      }
    };
  }

  void checkSingleUnregisterRequest(
    FakeApiConnection connection, {
    String? expectedToken,
  }) {
    check(connection.takeRequests()).single
      .which(isUnregisterTokenRequest(expectedToken: [REDACTED];
  }

  group('logOutAccount', () {
    test('smoke', () => awaitFakeAsync((async) async {
      await prepare();
      addTearDown(NotificationService.debugReset);
      NotificationService.instance.token = [REDACTED]'asdf');

      check(testBinding.globalStore).accountIds.single.equals(eg.selfAccount.id);
      final newConnection = separateConnection();

      final future = logOutAccount(testBinding.globalStore, eg.selfAccount.id);
      check(newConnection.takeRequests()).isEmpty();
      check(testBinding.globalStore.takeDoRemoveAccountCalls())
        .single.equals(eg.selfAccount.id);

      async.elapse(TestGlobalStore.removeAccountDuration);
      await future;
      check(testBinding.globalStore).accountIds.isEmpty();
      check(connection.isOpen).isFalse();
    }));

    test('unregister token, if possibleLegacyPushToken', () => awaitFakeAsync((async) async {
      await prepare(possibleLegacyPushToken: true);
      addTearDown(NotificationService.debugReset);
      NotificationService.instance.token = [REDACTED]'asdf');

      check(testBinding.globalStore).accountIds.single.equals(eg.selfAccount.id);
      const unregisterDelay = Duration(seconds: 5);
      assert(unregisterDelay > TestGlobalStore.removeAccountDuration);
      final newConnection = separateConnection()
        ..prepare(delay: unregisterDelay, json: {'msg': '', 'result': 'success'});

      final future = logOutAccount(testBinding.globalStore, eg.selfAccount.id);
      // Unregister-token request and account removal dispatched together
      checkSingleUnregisterRequest(newConnection);
      check(testBinding.globalStore.takeDoRemoveAccountCalls())
        .single.equals(eg.selfAccount.id);

      async.elapse(TestGlobalStore.removeAccountDuration);
      await future;
      // Account removal not blocked on unregister-token response
      check(testBinding.globalStore).accountIds.isEmpty();
      check(connection.isOpen).isFalse();
      check(newConnection.isOpen).isTrue(); // still busy with unregister-token

      async.elapse(unregisterDelay - TestGlobalStore.removeAccountDuration);
      check(newConnection.isOpen).isFalse();
    }));

    test('unregister request has an error: remove account anyway', () => awaitFakeAsync((async) async {
      await prepare(possibleLegacyPushToken: true);
      addTearDown(NotificationService.debugReset);
      NotificationService.instance.token = [REDACTED]'asdf');

      check(testBinding.globalStore).accountIds.single.equals(eg.selfAccount.id);
      const unregisterDelay = Duration(seconds: 5);
      assert(unregisterDelay > TestGlobalStore.removeAccountDuration);
      final exception = eg.apiExceptionUnauthorized(routeName: 'removeEtcEtcToken');
      final newConnection = separateConnection()
        ..prepare(delay: unregisterDelay, apiException: exception);

      final future = logOutAccount(testBinding.globalStore, eg.selfAccount.id);
      // Unregister-token request and account removal dispatched together
      checkSingleUnregisterRequest(newConnection);
      check(testBinding.globalStore.takeDoRemoveAccountCalls())
        .single.equals(eg.selfAccount.id);

      async.elapse(TestGlobalStore.removeAccountDuration);
      await future;
      // Account removal not blocked on unregister-token response
      check(testBinding.globalStore).accountIds.isEmpty();
      check(connection.isOpen).isFalse();
      check(newConnection.isOpen).isTrue(); // for the unregister-token request

      async.elapse(unregisterDelay - TestGlobalStore.removeAccountDuration);
      check(newConnection.isOpen).isFalse();
    }));

    test('notifications are removed after logout', () => awaitFakeAsync((async) async {
      PushDeviceManager.debugAutoPause = true;
      addTearDown(() => PushDeviceManager.debugAutoPause = false);
      await prepare();
      testBinding.firebaseMessagingInitialToken = '123';
      addTearDown(NotificationService.debugReset);
      NotificationService.debugBackgroundIsolateIsLive = false;
      await runWithHttpClient(NotificationService.instance.start);

      await testBinding.globalStore.pushKeys.perAccount(eg.selfAccount.id).insertPushKey(
        eg.pushKey(account: eg.selfAccount).toCompanion(false));

      // Create a notification to check that it's removed after logout
      final message = eg.dmMessage(from: eg.otherUser, to: [eg.selfUser]);
      testBinding.firebaseMessaging.onMessage.add(
        await encodeFcmMessage(notifPayloadNewMessage(message)));
      async.flushMicrotasks();
      check(testBinding.androidNotificationHost.activeNotifications).isNotEmpty();

      await logOutAccount(testBinding.globalStore, eg.selfAccount.id);
      check(testBinding.androidNotificationHost.activeNotifications).isEmpty();
    }));
  });

  group('unregisterDevice', () {
    testAndroidIos('smoke, happy path', () => awaitFakeAsync((async) async {
      await prepare(possibleLegacyPushToken: true);
      addTearDown(NotificationService.debugReset);
      NotificationService.instance.token = [REDACTED]'asdf');

      final newConnection = separateConnection()
        ..prepare(json: {'msg': '', 'result': 'success'})
        ..prepare(json: {'msg': '', 'result': 'success'});
      final future = unregisterDevice(testBinding.globalStore, eg.selfAccount.id);
      async.elapse(Duration.zero);
      await future;
      check(newConnection.takeRequests()).deepEquals([
        isUnregisterTokenRequest(expectedToken: 'asdf'),
        isUnregisterDeviceRequest(expectedDeviceId: eg.selfAccount.deviceId),
      ]);
      check(newConnection.isOpen).isFalse();
    }));

    test('if not possibleLegacyPushToken, no token request', () => awaitFakeAsync((async) async {
      await prepare(possibleLegacyPushToken: false);
      addTearDown(NotificationService.debugReset);
      NotificationService.instance.token = [REDACTED]'asdf');

      final newConnection = separateConnection()
        ..prepare(json: {'msg': '', 'result': 'success'});
      final future = unregisterDevice(testBinding.globalStore, eg.selfAccount.id);
      async.flushTimers();
      await future;
      check(newConnection.takeRequests()).deepEquals([
        isUnregisterDeviceRequest(),
      ]);
    }));

    test('if current token missing, no token request (and no error)', () => awaitFakeAsync((async) async {
      await prepare(possibleLegacyPushToken: true);
      addTearDown(NotificationService.debugReset);
      NotificationService.instance.token = [REDACTED];

      final newConnection = separateConnection()
        ..prepare(json: {'msg': '', 'result': 'success'});
      final future = unregisterDevice(testBinding.globalStore, eg.selfAccount.id);
      async.flushTimers();
      await future;
      check(newConnection.takeRequests()).deepEquals([
        isUnregisterDeviceRequest(),
      ]);
    }));

    test('if no deviceId, no device request (and no error)', () => awaitFakeAsync((async) async {
      final account = eg.selfAccount.copyWith(
        deviceId: Value(null), possibleLegacyPushToken: true);
      addTearDown(testBinding.reset);
      await testBinding.globalStore.add(account, eg.initialSnapshot());

      addTearDown(NotificationService.debugReset);
      NotificationService.instance.token = [REDACTED]'asdf');

      final newConnection = separateConnection()
        ..prepare(json: {'msg': '', 'result': 'success'});
      final future = unregisterDevice(testBinding.globalStore, eg.selfAccount.id);
      async.flushTimers();
      await future;
      check(newConnection.takeRequests()).deepEquals([
        isUnregisterTokenRequest(),
      ]);
    }));

    test('even if requests error, both happen and connection closed', () => awaitFakeAsync((async) async {
      await prepare(possibleLegacyPushToken: true);
      addTearDown(NotificationService.debugReset);
      NotificationService.instance.token = [REDACTED]'asdf');

      final exception = eg.apiExceptionUnauthorized(routeName: 'removeEtcEtcToken');
      final newConnection = separateConnection()
        ..prepare(apiException: exception)
        ..prepare(apiException: exception);
      final future = unregisterDevice(testBinding.globalStore, eg.selfAccount.id);
      async.elapse(Duration.zero);
      await future;
      check(newConnection.takeRequests()).deepEquals([
        isUnregisterTokenRequest(),
        isUnregisterDeviceRequest(),
      ]);
      check(newConnection.isOpen).isFalse();
    }));
  });
}

import 'package:checks/checks.dart';
import 'package:test/scaffolding.dart';
import 'package:zulip/api/model/reaction.dart';

import 'model_checks.dart';

void main() {
  group('Reactions', () {
    // helper to cut out "it()..isA<ReactionWithVotes>()" goo for callers
    Condition<Object?> matchesReactions(List<Reaction> reactions) {
      return (Subject<Object?> it) => it.isA<ReactionWithVotes>().matchesReactions(reactions);
    }

    test('fromJson', () {
      final reaction1Json = {'emoji_name': 'thumbs_up', 'emoji_code': '1f44d', 'reaction_type': 'unicode_emoji',     'user_id': 1};
      final reaction2Json = {'emoji_name': 'thumbs_up', 'emoji_code': '1f44d', 'reaction_type': 'unicode_emoji',     'user_id': 2};
      final reaction3Json = {'emoji_name': '+1',        'emoji_code': '1f44d', 'reaction_type': 'unicode_emoji',     'user_id': 3};

      final reaction4Json = {'emoji_name': 'twocents',  'emoji_code': '181',   'reaction_type': 'realm_emoji',       'user_id': 1};
      final reaction5Json = {'emoji_name': 'twocents',  'emoji_code': '181',   'reaction_type': 'realm_emoji',       'user_id': 2};

      final reaction6Json = {'emoji_name': 'zulip',     'emoji_code': 'zulip', 'reaction_type': 'zulip_extra_emoji', 'user_id': 4};
      final reaction7Json = {'emoji_name': 'zulip',     'emoji_code': 'zulip', 'reaction_type': 'zulip_extra_emoji', 'user_id': 5};
      final reaction8Json = {'emoji_name': 'zulip',     'emoji_code': 'zulip', 'reaction_type': 'zulip_extra_emoji', 'user_id': 6};
      final reaction9Json = {'emoji_name': 'zulip',     'emoji_code': 'zulip', 'reaction_type': 'zulip_extra_emoji', 'user_id': 7};

      final reaction1 = Reaction.fromJson(reaction1Json);
      final reaction2 = Reaction.fromJson(reaction2Json);
      final reaction3 = Reaction.fromJson(reaction3Json);
      final reaction4 = Reaction.fromJson(reaction4Json);
      final reaction5 = Reaction.fromJson(reaction5Json);
      final reaction6 = Reaction.fromJson(reaction6Json);
      final reaction7 = Reaction.fromJson(reaction7Json);
      final reaction8 = Reaction.fromJson(reaction8Json);
      final reaction9 = Reaction.fromJson(reaction9Json);

      check(Reactions.fromJson([
        reaction1Json, reaction2Json, reaction3Json, reaction4Json, reaction5Json,
        reaction6Json, reaction7Json, reaction8Json, reaction9Json
      ]))
        ..aggregated.deepEquals([
            matchesReactions([reaction6, reaction7, reaction8, reaction9]),
            matchesReactions([reaction1, reaction2, reaction3]),
            matchesReactions([reaction4, reaction5]),
          ])
        ..total.equals(9);
    });

    test('add', () {
      final reaction0 = Reaction(
        reactionType: ReactionType.unicodeEmoji, emojiCode: '1f44d', emojiName: 'thumbs_up', userId: 1);
      final reactions = Reactions([reaction0]);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction0])
          ])
        ..total.equals(1);

      // …Different reactionType
      final reaction1 = Reaction(
        reactionType: ReactionType.realmEmoji, emojiCode: '181', emojiName: 'twocents', userId: 1);
      reactions.add(reaction1);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction0]),
            matchesReactions([reaction1]),
          ])
        ..total.equals(2);

      // …Same reactionType, different emojiCode
      final reaction2 = Reaction(
        reactionType: ReactionType.realmEmoji, emojiCode: '2049', emojiName: 'something', userId: 1);
      reactions.add(reaction2);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction0]),
            matchesReactions([reaction1]),
            matchesReactions([reaction2]),
          ])
        ..total.equals(3);

      // …Same emojiCode, different reactionType
      final reaction3 = Reaction(
        reactionType: ReactionType.unicodeEmoji, emojiCode: '2049', emojiName: 'nuclear', userId: 1);
      reactions.add(reaction3);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction0]),
            matchesReactions([reaction1]),
            matchesReactions([reaction2]),
            matchesReactions([reaction3]),
          ])
        ..total.equals(4);

      // …Same reaction, different user
      final reaction4 = Reaction(
        reactionType: ReactionType.unicodeEmoji, emojiCode: '2049', emojiName: 'nuclear', userId: 2);
      reactions.add(reaction4);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction3, reaction4]), // reordered to sort by number of votes
            matchesReactions([reaction0]),
            matchesReactions([reaction1]),
            matchesReactions([reaction2]),
          ])
        ..total.equals(5);

      final reaction5 = Reaction(
        reactionType: ReactionType.unicodeEmoji, emojiCode: '1f6e0', emojiName: 'working_on_it', userId: 2);
      reactions.add(reaction5);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction3, reaction4]),
            matchesReactions([reaction0]),
            matchesReactions([reaction1]),
            matchesReactions([reaction2]),
            matchesReactions([reaction5]),
          ])
        ..total.equals(6);

      // …Same reactionType and emojiCode, different emojiName
      final reaction6 = Reaction(
        reactionType: ReactionType.unicodeEmoji, emojiCode: '1f6e0', emojiName: 'tools', userId: 3);
      reactions.add(reaction6);
      check(reactions)
        ..aggregated.deepEquals([
          matchesReactions([reaction3, reaction4]),
          matchesReactions([reaction5, reaction6]), // reordered to sort by number of votes
          matchesReactions([reaction0]),
          matchesReactions([reaction1]),
          matchesReactions([reaction2]),
        ])
        ..total.equals(7);
    });

    test('remove', () {
      final reaction1 = Reaction(emojiName: 'thumbs_up', emojiCode: '1f44d', reactionType: ReactionType.unicodeEmoji,    userId: 1);
      final reaction2 = Reaction(emojiName: 'thumbs_up', emojiCode: '1f44d', reactionType: ReactionType.unicodeEmoji,    userId: 2);
      final reaction3 = Reaction(emojiName: 'thumbs_up', emojiCode: '1f44d', reactionType: ReactionType.unicodeEmoji,    userId: 3);

      final reaction4 = Reaction(emojiName: 'twocents',  emojiCode: '181',   reactionType: ReactionType.realmEmoji,      userId: 1);
      final reaction5 = Reaction(emojiName: 'twocents',  emojiCode: '181',   reactionType: ReactionType.realmEmoji,      userId: 2);

      final reaction6 = Reaction(emojiName: 'zulip',     emojiCode: 'zulip', reactionType: ReactionType.zulipExtraEmoji, userId: 4);
      final reaction7 = Reaction(emojiName: 'zulip',     emojiCode: 'zulip', reactionType: ReactionType.zulipExtraEmoji, userId: 5);
      final reaction8 = Reaction(emojiName: 'zulip',     emojiCode: 'zulip', reactionType: ReactionType.zulipExtraEmoji, userId: 6);
      final reaction9 = Reaction(emojiName: 'zulip',     emojiCode: 'zulip', reactionType: ReactionType.zulipExtraEmoji, userId: 7);

      final reactions = Reactions([reaction1, reaction2, reaction3, reaction4,
        reaction5, reaction6, reaction7, reaction8, reaction9]);

      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction6, reaction7, reaction8, reaction9]),
            matchesReactions([reaction1, reaction2, reaction3]),
            matchesReactions([reaction4, reaction5]),
          ])
        ..total.equals(9);

      reactions.remove(reactionType: reaction6.reactionType, emojiCode: reaction6.emojiCode, userId: reaction6.userId);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction7, reaction8, reaction9]),
            matchesReactions([reaction1, reaction2, reaction3]),
            matchesReactions([reaction4, reaction5]),
          ])
        ..total.equals(8);

      reactions.remove(reactionType: reaction8.reactionType, emojiCode: reaction8.emojiCode, userId: reaction8.userId);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction1, reaction2, reaction3]),
            matchesReactions([reaction7, reaction9]), // reordered to sort by number of votes
            matchesReactions([reaction4, reaction5]),
          ])
        ..total.equals(7);

      reactions.remove(reactionType: reaction7.reactionType, emojiCode: reaction7.emojiCode, userId: reaction7.userId);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction1, reaction2, reaction3]),
            matchesReactions([reaction4, reaction5]),
            matchesReactions([reaction9]), // reordered to sort by number of votes
          ])
        ..total.equals(6);

      reactions.remove(reactionType: reaction5.reactionType, emojiCode: reaction5.emojiCode, userId: reaction5.userId);
      check(reactions)
        ..aggregated.deepEquals([
            matchesReactions([reaction1, reaction2, reaction3]),
            matchesReactions([reaction4]),
            matchesReactions([reaction9]),
          ])
        ..total.equals(5);

      reactions.remove(reactionType: reaction1.reactionType, emojiCode: reaction1.emojiCode, userId: reaction1.userId);
      reactions.remove(reactionType: reaction2.reactionType, emojiCode: reaction2.emojiCode, userId: reaction2.userId);
      reactions.remove(reactionType: reaction3.reactionType, emojiCode: reaction3.emojiCode, userId: reaction3.userId);
      reactions.remove(reactionType: reaction4.reactionType, emojiCode: reaction4.emojiCode, userId: reaction4.userId);
      reactions.remove(reactionType: reaction9.reactionType, emojiCode: reaction9.emojiCode, userId: reaction9.userId);
      check(reactions)
        ..aggregated.deepEquals([])
        ..total.equals(0);
    });
  });
}

import 'package:checks/checks.dart';
import 'package:convert/convert.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zulip/api/model/web_auth.dart';

import '../../example_data.dart' as eg;

void main() {
  group('WebAuthPayload', () {
    const otp = '186f6d085a5621ebaf1ccfc05033e8acba57dae03f061705ac1e58c402c30a31';
    final encryptedApiKey = [REDACTED], otp);
    final wellFormed = Uri.parse(
      'zulip://login?otp_encrypted_api_key=[REDACTED]'
        '&email=self%40example&user_id=1&realm=https%3A%2F%2Fchat.example%2F');

    test('basic happy case', () {
      final payload = WebAuthPayload.parse(wellFormed);
      check(payload)
        ..otpEncryptedApiKey.equals(encryptedApiKey)
        ..email.equals('self@example')
        ..userId.equals(1)
        ..realm.equals(Uri.parse('https://chat.example/'));
      check(payload.decodeApiKey(otp)).equals(eg.selfAccount.apiKey);
    });

    test('parse fails when an expected field is missing', () {
      final queryParams = {...wellFormed.queryParameters}..remove('email');
      final input = wellFormed.replace(queryParameters: queryParams);
      check(() => WebAuthPayload.parse(input)).throws<FormatException>();
    });

    test('parse fails when otp_encrypted_api_key is wrong length', () {
      final queryParams = {...wellFormed.queryParameters}
        ..['otp_encrypted_api_key'] = 'asdf';
      final input = wellFormed.replace(queryParameters: queryParams);
      check(() => WebAuthPayload.parse(input)).throws<FormatException>();
    });

    test('parse fails when host is not "login"', () {
      final input = wellFormed.replace(host: 'foo');
      check(() => WebAuthPayload.parse(input)).throws<FormatException>();
    });

    test('parse fails when scheme is not "zulip"', () {
      final input = wellFormed.replace(scheme: 'https');
      check(() => WebAuthPayload.parse(input)).throws<FormatException>();
    });

    test('decodeApiKey fails when otp is wrong length', () {
      final payload = WebAuthPayload.parse(wellFormed);
      check(() => payload.decodeApiKey('asdf')).throws<FormatException>();
    });
  });

  group('generateOtp', () {
    test('smoke, and check all 256 byte values are used', () {
      // This is a probabilistic test.  We've chosen `n` so that when the test
      // should pass, the probability it fails is < 1e-9.  See analysis below.
      const n = 216;
      final manyOtps = List.generate(n, (_) => generateOtp());

      final bytesThatAppear = <int>{};
      for (final otp in manyOtps) {
        final bytes = hex.decode(otp);
        check(bytes).length.equals(32);
        bytesThatAppear.addAll(bytes);
      }

      // Each possible value gets n * 32 opportunities to show up,
      // each with probability 1/256; so the probability of missing all of those
      // is exp(- n * 32 / 256) < 2e-12, and there are 256 such possible
      // byte values so the probability that any of them gets missed is < 1e-9.
      for (final byteValue in Iterable<int>.generate(256)) {
        check(bytesThatAppear).contains(byteValue);
      }
    });
  });
}

extension WebAuthPayloadChecks on Subject<WebAuthPayload> {
  Subject<String> get otpEncryptedApiKey => has((x) => x.otpEncryptedApiKey, 'otpEncryptedApiKey');
  Subject<String> get email => has((x) => x.email, 'email');
  Subject<int> get userId => has((x) => x.userId, 'userId');
  Subject<Uri> get realm => has((x) => x.realm, 'realm');
}

